// Canonical string: "v1:" + ts + ":" + METHOD + ":" + pathname + ":" + rawBody
const crypto = require('crypto');
function sign(secret, method, pathname, rawBody) {
  const ts = String(Math.floor(Date.now() / 1000));
  const hex = crypto.createHmac('sha256', secret).update('v1:' + ts + ':' + method + ':' + pathname + ':' + rawBody).digest('hex');
  return { 'X-LendLoop-Timestamp': ts, 'X-LendLoop-Signature': 'v1=' + hex };
}
const SECRET = $env.N8N_TO_CONVEX_SECRET;
if (!SECRET) throw new Error('N8N_TO_CONVEX_SECRET is not set in the n8n container');
const BASE = String($env.CONVEX_SITE_URL || '').replace(/\/+$/, '');
if (!BASE) throw new Error('CONVEX_SITE_URL is not set in the n8n container');
// Keep error text short and free of e-mail addresses before it leaves n8n.
const clean = (s, n) => String(s || '').replace(/[^\s@<>]+@[^\s@<>]+/g, '[email]').replace(/\s+/g, ' ').slice(0, n);
const PATHNAME = '/n8n/workflow-errors';
const x = $json.execution || {};
const report = {
  executionId: String(x.id ?? 'unknown'),
  workflowName: clean($json.workflow?.name, 120),
  nodeName: clean(x.lastNodeExecuted, 120),
  message: clean(x.error?.message, 300),
};
console.error('LendLoop workflow error', JSON.stringify(report)); // also kept in this execution's log
const body = JSON.stringify(report);
return [{ json: { url: BASE + PATHNAME, body, headers: sign(SECRET, 'POST', PATHNAME, body), report } }];
